import React, { useEffect, useState } from 'react';
import styles from './PostsFeed.module.scss';
import PostCard from '../PostCard/PostCard';
import { api } from '../../utils/api';

const extractPosts = (payload) => {
  if (Array.isArray(payload?.data)) {
    return payload.data;
  }

  if (Array.isArray(payload)) {
    return payload;
  }

  return [];
};

export default function PostsFeed({ user }) {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    let isCancelled = false;

    const loadPosts = async () => {
      try {
        setLoading(true);
        setError('');
        const response = await api.get('/posts');

        if (isCancelled) {
          return;
        }

        const authorId = String(user?.id || user?.ID || '');
        const allPosts = extractPosts(response);
        const filteredPosts = allPosts.filter((post) => (
          String(post?.author_id || post?.author?.id || post?.author?.ID || '') === authorId
        ));

        setPosts(filteredPosts);
      } catch (requestError) {
        if (!isCancelled) {
          setError(requestError.message || 'Не успяхме да заредим постовете.');
        }
      } finally {
        if (!isCancelled) {
          setLoading(false);
        }
      }
    };

    if (user?.id || user?.ID) {
      loadPosts();
    }

    return () => {
      isCancelled = true;
    };
  }, [user]);

  if (loading) {
    return <div className={styles.feedback}>Зареждаме постовете...</div>;
  }

  if (error) {
    return <div className={styles.feedback}>{error}</div>;
  }

  if (posts.length === 0) {
    return <div className={styles.feedback}>Този профил все още няма публикувани постове.</div>;
  }

  return (
    <div className={styles.postsFeed}>
      {posts.map((post) => (
        <PostCard key={post.id || post.ID} post={post} />
      ))}
    </div>
  );
}
